#: Total used when the old share was only a percentage: 7.01 % is 701/10,000.
PERCENT_TOTAL = 10_000


def copy_tantiemes(apps, schema_editor):
    """Keep the old "coproperty share / shares count" as the coproperty shares.

    A whole share that does not exceed a whole count of at least 1 is the
    tantièmes of the lot and the total of the coproperty (250 of 1,000).
    Otherwise a share up to 100 is the percentage its label asked for,
    written in ten-thousandths (7.01 % is 701 of 10,000). Both become the
    voting and the common charges shares, the usual case; anything else is
    dropped.
    """
    Property = apps.get_model("property", "Property")
    for prop in Property.objects.exclude(coproperty_share=None):
        share, count = prop.coproperty_share, prop.shares_count
        if (
            count is not None
            and count >= 1
            and share == share.to_integral_value()
            and count == count.to_integral_value()
            and 0 <= share <= count
        ):
            lot, total = int(share), int(count)
        elif 0 < share <= 100:
            lot, total = round(share * 100), PERCENT_TOTAL
        else:
            continue
        prop.voting_tantiemes = prop.charges_tantiemes = lot
        prop.voting_tantiemes_total = prop.charges_tantiemes_total = total
        prop.save(
            update_fields=[
                "voting_tantiemes",
                "voting_tantiemes_total",
                "charges_tantiemes",
                "charges_tantiemes_total",
            ]
        )


